138	/// Migrate evidence only for a new reception, in the existing transcript commit.
139	/// Account DMs relocate the raw device conversation into their canonical account
140	/// conversation. Exact account + signed event ID binds provenance across that
141	/// relocation; the transcript still requires the exact canonical source tuple.
142	pub(super) fn project_on(
143	    c: &Connection,
144	    account: &[u8; 32],
145	    source: ReceptionSource,
146	) -> Result<(), LogError> {
147	    let ambiguous: bool = c.query_row("SELECT count(*)>1 FROM (SELECT 1 FROM pending_ingress_origins WHERE account=?1 AND event_id=?2 LIMIT 2)",params![account.as_slice(),source.event_id.as_bytes().as_slice()],|r|r.get(0))?;
148	    if ambiguous {
149	        return Err(invalid("ambiguous ingress source domain"));
150	    }
151	    c.execute("INSERT INTO transcript_ingress_origins(ordinal,account,via,peer_device) SELECT t.ordinal,p.account,p.via,p.peer_device FROM transcript_rows t JOIN pending_ingress_origins p ON p.account=?1 AND p.event_id=t.row_key WHERE t.kind=?2 AND t.conversation=?3 AND t.row_key=?4 ON CONFLICT(ordinal) DO NOTHING", params![account.as_slice(), source.kind.transcript_kind(),source.conversation.as_bytes().as_slice(),source.event_id.as_bytes().as_slice()])?;
152	    c.execute(
153	        "DELETE FROM pending_ingress_origins WHERE account=?1 AND event_id=?2",
154	        params![account.as_slice(), source.event_id.as_bytes().as_slice()],
155	    )?;
156	    Ok(())
157	}
