 66	pub(super) fn validate_cursor(
 67	    state: &StreamState,
 68	    cursor: ReceptionCursor,
 69	) -> Result<(), LogError> {
 70	    if cursor.epoch != state.head.epoch
 71	        || cursor.sequence > state.head.sequence
 72	        || cursor.sequence < state.retired
 73	    {
 74	        return Err(LogError::StaleCursor);
 75	    }
 76	    Ok(())
 77	}
