 79	/// Called inside the existing plaintext/evidence transaction, before its journal
 80	/// intent is retired. The source body must already exist in that transaction.
 81	pub(crate) fn install_on(
 82	    c: &Connection,
 83	    source: ReceptionSource,
 84	    metadata: &ReceptionMetadata,
 85	) -> Result<u64, LogError> {
 86	    metadata.validate(source.kind)?;
 87	    let account = active_account_on(c)?;
 88	    ensure_stream_on(c, &account)?;
 89	    let terminal_key = if metadata.reception_only {
 90	        metadata.batch_id.as_deref().unwrap_or_default()
 91	    } else {
 92	        ""
 93	    };
 94	    let previous: Option<i64> = c.query_row(
 95	        "SELECT sequence FROM reception_identities WHERE kind=?1 AND conversation=?2 AND event_id=?3 AND terminal_key=?4 AND account=?5",
 96	        params![source.kind.tag(),source.conversation.as_bytes().as_slice(),source.event_id.as_bytes().as_slice(),terminal_key,account.as_slice()], |row|row.get(0),
 97	    ).optional()?;
 98	    if let Some(sequence) = previous {
 99	        return natural(sequence);
100	    }
101	    if !metadata.reception_only {
102	        let exists: bool = c.query_row("SELECT EXISTS(SELECT 1 FROM transcript_rows WHERE kind=?1 AND conversation=?2 AND row_key=?3)",
103	            params![source.kind.transcript_kind(),source.conversation.as_bytes().as_slice(),source.event_id.as_bytes().as_slice()],|row|row.get(0))?;
104	        if !exists {
105	            return Err(invalid(
106	                "reception effect has no installed transcript source",
107	            ));
108	        }
109	    }
110	    let encoded =
111	        bincode::serialize(metadata).map_err(|_| invalid("invalid reception encoding"))?;
112	    if encoded.len() > MAX_METADATA_BYTES {
113	        return Err(invalid("reception metadata exceeds budget"));
114	    }
115	    c.execute("INSERT INTO reception_identities(kind,conversation,event_id,terminal_key,account) VALUES(?1,?2,?3,?4,?5)",params![source.kind.tag(),source.conversation.as_bytes().as_slice(),source.event_id.as_bytes().as_slice(),terminal_key,account.as_slice()])?;
116	    let sequence = c.last_insert_rowid();
117	    c.execute(
118	        "INSERT INTO reception_pending VALUES(?1,?2)",
119	        params![sequence, encoded],
120	    )?;
121	    if c.execute(
122	        "UPDATE reception_stream SET high_water=?1 WHERE account=?2 AND high_water<?1",
123	        params![sequence, account.as_slice()],
124	    )? != 1
125	    {
126	        return Err(invalid("reception sequence did not advance"));
127	    }
128	    if !metadata.reception_only {
129	        super::origins::project_on(c, &account, source)?;
130	    }
131	    natural(sequence)
132	}
