pub(in crate::node) fn published_projection(
    &self,
    channel: ConversationId,
) -> Result<Option<super::super::ChannelMembershipProjection>, LogError> {
    let binding: Option<(Vec<u8>, i64, i64)> = self.profile.database().read(|c| {
        self.check_account_on(c)?;
        c.prepare_cached(PUBLISHED_PROJECTION_SQL)?
            .query_row(
                params![channel.as_bytes().as_slice(), self.account.as_slice()],
                |r| Ok((r.get(0)?, r.get(1)?, r.get(2)?)),
            )
            .optional()
            .map_err(Into::into)
    })?;
    let Some((job, revision, count)) = binding else {
        return Ok(None);
    };
    let job: [u8; 16] = job
        .try_into()
        .map_err(|_| invalid("invalid channel current job"))?;
    self.profile.database().read(|c| {
        self.check_account_on(c)?;
        replay::require_source_on(c, channel, job, revision)
    })?;
    #[cfg(test)]
    PROJECTION_HYDRATIONS.with(|count| count.set(count.get() + 1));
    let (reducer, next) = super::super::projection_facts::ProjectionFacts::load(
        self.profile.clone(),
        job,
        channel,
    )?;
    if next != count {
        return Err(LogError::StaleCursor);
    }
    self.profile.database().read(|c| {
        self.check_account_on(c)?;
        replay::require_source_on(c, channel, job, revision)
    })?;
    Ok(Some(reducer.finish()))
}

/// A network-only prepared prefix is not a published current channel.
/// Its owner validates unchanged raw controls/destructive state each turn.

//! Last completely validated presentation is separate from fresh admission.
//! Startup may display this current metadata while signed control work resumes.
use super::*;
use bincode::Options;
use serde::{Deserialize, Serialize};
mod preparation;
pub(super) use preparation::PolicyCandidate;

const SCHEMA: &str = "
CREATE TABLE channel_book_metadata(
 channel BLOB PRIMARY KEY CHECK(length(channel)=32),owner_account BLOB NOT NULL CHECK(length(owner_account)=32),generation INTEGER NOT NULL,
 job BLOB NOT NULL CHECK(length(job)=16),stamp INTEGER NOT NULL,replica_stamp INTEGER NOT NULL,
 state BLOB NOT NULL,presentation BLOB NOT NULL
) WITHOUT ROWID;
";

#[derive(Serialize, Deserialize)]
pub(super) struct Presentation {
    pub(super) policy: crate::channel::HistoryPolicy,
    pub(super) preferences: Vec<(String, u64, EventId, bool)>,
    pub(super) departed: bool,
    pub(super) transferred: bool,
}
