        let deadline = Instant::now() + Duration::from_secs(8);
        loop {
            let (tx, rx) = mpsc::sync_channel(1);
            let title = title.clone();
            let reply = RcBlock::new(move |items: NonNull<NSArray<UNNotification>>| {
